function onboardingPage(){return `<div class="eyebrow">CookieTime 시작하기</div><h1 class="page-title">필요한 권한을<br>차근차근 준비해요</h1><p class="page-subtitle">앱 사용 감지와 화면 위 쿠키 알림은 Android 권한이 있어야 작동해요. 허용 여부는 설정에서 언제든 바꿀 수 있어요.</p><div class="card settings-list"><strong>먼저 확인할 권한</strong><p>① 앱 사용 기록: 선택한 앱에 들어갔는지 감지</p><p>② 다른 앱 위에 표시: 다른 화면 위에 쿠키 바 표시</p><p>③ 알림: 과제 시작·마감 알림 받기</p><p>④ 정확한 알람: 앱이 닫혀도 예약 시각에 알림</p><div class="notice">가입 없이 바로 사용할 수 있고, 기록은 이 기기에 저장됩니다. 필요한 권한은 설정에서 언제든 확인할 수 있어요.</div><button class="button full" data-onboarding="settings">권한 설정 확인하기</button><button class="button ghost full" data-onboarding="skip">가입 없이 둘러보기</button><button class="text-link full account-onboarding-link" data-open-account>Google 로그인</button></div>`}function render(){const root=document.querySelector('#app');root.innerHTML=(!state.settings.onboardingDone?onboardingPage():({home:homePage,schedule:schedulePage,tasks:tasksPage,focus:focusPage,settings:settingsPage,game:gamePage,stats:statsPage}[page]||homePage)());root.querySelectorAll('.hero img,.focus-character').forEach(image=>image.hidden=!state.settings.character);if(page==='focus'&&state.settings.character){const bubble=document.createElement('div');bubble.className='character-bubble';bubble.textContent=state.focus.deviation?'잠깐 쉬어도 괜찮아요.':state.focus.active?(state.focus.speech||'쿠키와 함께 차근차근 해봐요!'):'준비되면 같이 시작해요!';root.querySelector('.focus-hero')?.prepend(bubble)}if(page==='schedule'){const header=root.querySelector('.page-heading>div:last-child');if(header){const button=document.createElement('button');button.className='button secondary';button.textContent='이미지 가져오기';button.onclick=openTimetableOcr;header.prepend(button)}}if(page==='settings'){const card=document.createElement('section');card.className='card settings-list';card.innerHTML=`<strong>스트릭 기준</strong><label class="field-label">하루 인정 기준<select class="select" id="streak-criterion"><option value="onTime" ${state.settings.streakCriterion==='onTime'?'selected':''}>예정 시간에 과제 시작</option><option value="deviation" ${state.settings.streakCriterion==='deviation'?'selected':''}>이탈 목표 지키기</option><option value="any" ${state.settings.streakCriterion==='any'?'selected':''}>위 조건 중 하나</option></select><small class="eyebrow">예정 시각 ±5분 내에 과제 알림의 ‘집중 시작’을 누르면 인정돼요.</small></label><label class="field-label">하루 앱 이탈 목표(분)<input class="input" id="deviation-goal" type="number" min="0" max="600" value="${state.settings.dailyDeviationGoalMinutes||60}"/></label><label class="field-label">수업 종료 알림 <button class="switch ${state.settings.classEndReminders!==false?'on':''}" data-setting="classEndReminders"></button></label><label class="field-label">방해 앱 사용 기본 시간(분)<select class="select" id="usage-default">${[5,10,15,30].map(n=>`<option value="${n}" ${Number(state.settings.usageDefaultMinutes||15)===n?'selected':''}>${n}분</option>`).join('')}</select></label>`;root.append(card)}if(page==='stats'){const records=(state.dailyRecords||[]).filter(r=>Date.now()-new Date(r.date+'T00:00:00').getTime()<7*86400000),total=records.reduce((sum,r)=>sum+(r.scheduledStarts||0),0),ontime=records.reduce((sum,r)=>sum+(r.onTimeStarts||0),0),box=document.createElement('div');box.className='notice';box.textContent='최근 7일 예정 시각 ±5분 내 과제 시작 비율: '+(total?Math.round(ontime/total*100):0)+'% ('+ontime+'/'+total+')';root.prepend(box)}if(page==='focus'){const reward=document.createElement('section');reward.className='card cookie-reward-card';reward.innerHTML=cookieRewardsMarkup();const focusStats=root.querySelector('.stats-row');if(focusStats)focusStats.after(reward);else root.append(reward)}bindCommon()}
function openTimetableOcr(){const root=document.querySelector('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><h2>시간표 이미지 읽기</h2><button class="close" data-close>×</button></div><p class="page-subtitle">이미지는 기기 안에서 인식합니다. OCR 결과를 확인하고 수업을 직접 수정한 뒤 저장해주세요.</p><label class="field-label">시간표 이미지</label><input id="timetable-image" class="input" type="file" accept="image/*"/><p id="ocr-status" class="notice">이미지를 선택하면 한국어 OCR을 시작합니다. 첫 실행에는 OCR 엔진을 내려받아야 해요.</p><label class="field-label">인식 결과검토용</label><textarea id="ocr-text" class="textarea" rows="8" placeholder="인식된 텍스트가 여기에 표시됩니다"></textarea><div class="form-grid"><label class="field-label">과목명<input class="input" id="ocr-title" placeholder="과목명을 확인해 입력"/></label><label class="field-label">요일<select class="select" id="ocr-day">${weekdays.map((d,i)=>`<option value="${i}">${d}</option>`).join('')}</select></label></div><div class="form-grid"><label class="field-label">시작<input class="input" id="ocr-start" type="time" value="09:00"/></label><label class="field-label">종료<input class="input" id="ocr-end" type="time" value="10:30"/></label></div><button class="button full" id="ocr-save-class">검토한 수업 저장</button></section></div>`;root.querySelector('[data-close]').onclick=()=>root.innerHTML='';root.querySelector('#timetable-image').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;const status=root.querySelector('#ocr-status');try{status.textContent='이미지를 기기에서 분석하고 있어요…';if(!window.Tesseract){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';script.onload=resolve;script.onerror=reject;document.head.append(script)})}const worker=await Tesseract.createWorker('kor+eng');const result=await worker.recognize(file);root.querySelector('#ocr-text').value=result.data.text||'';await worker.terminate();const first=(result.data.text||'').split(/\r?\n/).map(s=>s.trim()).find(Boolean);if(first)root.querySelector('#ocr-title').value=first.slice(0,50);status.textContent='인식이 끝났어요. 결과를 검토하고 과목명·요일·시간을 수정한 뒤 저장해주세요.'}catch(error){console.warn('Timetable OCR unavailable',error);status.textContent='OCR 엔진을 불러오지 못했어요. 이미지와 수업 정보를 직접 확인해 입력해주세요.'}};root.querySelector('#ocr-save-class').onclick=()=>{const title=root.querySelector('#ocr-title').value.trim(),day=Number(root.querySelector('#ocr-day').value),start=root.querySelector('#ocr-start').value,end=root.querySelector('#ocr-end').value;if(!title||!start||!end||start>=end){showToast('과목명과 시작·종료 시간을 확인해주세요.');return}state.classes.push({id:crypto.randomUUID(),day,start,end,title,room:''});save();root.innerHTML='';selectedDay=day;render();showToast('검토한 수업을 시간표에 추가했어요')}}
function renderAccountButton(){const button=document.querySelector('#account-shortcut');if(button){button.textContent=authUser?'내 계정':'로그인';button.setAttribute('aria-label',authUser?'계정 설정':'Google 간편 로그인')}}
function openAccountModal(){if(authUser){showToast((authUser.displayName||'로그인 계정')+'으로 로그인되어 있어요.');return}const auth=window.CookieAuth;if(typeof auth?.signIn!=='function'){showToast('로그인 기능을 불러오지 못했어요.');return}Promise.resolve().then(()=>auth.signIn()).catch(error=>{console.warn('Google sign-in unavailable',error);showToast(error?.message==='Firebase web configuration is missing.'?'Google 로그인 설정이 아직 준비되지 않았어요.':'로그인 창을 열지 못했어요. 다시 시도해주세요.')})}function cookieRewardsMarkup(){const rewards=state.cookieRewards,total=rewards.loose+rewards.boxes*10,withinHour=(Number(state.focus.sessionSeconds)||0)%3600,next=Math.ceil((3600-withinHour)/60),nextHour=(state.focus.rewardedHours||0)+1,nextReward=nextHour>=5?'쿠키 5개':isCurrentClassGap()?'쿠키 2개':'쿠키 1개',inGap=isCurrentClassGap(),animateFrom=lastCookieRenderTotal===null?total:lastCookieRenderTotal,added=Math.max(0,total-animateFrom),layers=Math.min(5,total),burst=Math.min(layers,added);lastCookieRenderTotal=total;const stack=Array.from({length:layers},(_,index)=>{const absolute=total-layers+index,style=`--layer:${index};--lean:${index%2===0?-2:2}deg`,arriving=burst>0&&index>=layers-burst;return `<span class="stack-cookie cookie-flavor-${absolute%5} ${arriving?'cookie-arriving':''}" style="${style}" aria-hidden="true"><i></i><i></i><i></i></span>`}).join('');return `<section class="cookie-stack-scene"><div class="cookie-sun-glow"></div><span class="cookie-cloud cloud-one"></span><span class="cookie-cloud cloud-two"></span><svg class="cookie-mountains" viewBox="0 0 390 220" preserveAspectRatio="none" aria-hidden="true"><path d="M0 167 64 112 111 160 177 80 244 157 299 105 390 174v46H0Z" fill="#e5e5e2"/><path d="m137 132 40-52 40 57-22-9-18-20-19 23-9-12Z" fill="#fff"/><path d="M0 190 78 150l58 44 78-38 70 45 58-29 48 31v17H0Z" fill="#f0e5d1"/></svg><div class="cookie-height-label"><span class="cookie-summit"><i></i>${total>=5?'산 정상':total>0?'산을 오르는 중':'등반 준비'}</span><div><small>현재 고도</small><strong>${total*108}<em>m</em></strong></div></div><div class="cookie-stack-wrap"><div class="cookie-stack-pile">${stack}</div><div class="cookie-stack-base"></div></div><div class="cookie-scene-count">🍪 ${total}개</div></section><div class="cookie-reward-summary"><div class="stats-row cookie-reward-stats"><div class="stat"><strong>🍪 ${total}</strong><small>쌓인 쿠키</small></div><div class="stat"><strong>✦ ${rewards.gapBonus||0}</strong><small>공강 보너스</small></div><div class="stat"><strong>${next}분</strong><small>다음 ${nextReward}</small></div></div><p class="cookie-gap-bonus ${inGap?'active':''}">${inGap?'공강 집중 중 · 쿠키 보너스 적립':'공강시간 1시간 집중 시 쿠키 2개'}</p>${rewards.history.length?`<div class="cookie-reward-history">${rewards.history.slice(0,3).map(entry=>`<span>${entry.hour||1}시간 집중 · ${entry.gapBonus?'공강 보너스 쿠키 1개':`쿠키 ${entry.count||entry.multiplier||1}개`}</span>`).join('')}</div>`:'<p class="cookie-reward-empty">집중을 이어가면 쿠키가 층층이 쌓여요.</p>'}<button class="button secondary cookie-share-button" data-cookie-share>쿠키 보관함 이미지 저장·공유</button></div>`}
function homePage(){const next=sortedTasks().find(t=>!t.done);const list=sortedTasks().filter(t=>!t.done).slice(0,2);const cls=todayClasses();let free='오늘은 내 페이스대로 시작해봐요';if(cls.length>1){let a=cls[0].end,b=cls[1].start;if(a<b)free=`${a}부터 ${b}까지, 잠깐 숨 고를 시간`}else if(cls.length===1)free=`${cls[0].end} 이후에 여유가 있어요`;
return `<div class="eyebrow">${today.getMonth()+1}월 ${today.getDate()}일${dayLabel(today.getDay())}</div><h1 class="page-title">오늘도 가볍게 시작해요</h1><p class="page-subtitle">작은 시작이 하루의 리듬을 바꿔요.</p>
<section class="hero"><div class="hero-copy"><span class="pill"><i class="pill-dot"></i>오늘의 쿠키</span><h2>${state.focus.active?'집중 중이야!\n조금만 더 같이 가자':'오늘 할 일,\n하나씩 해볼까?'}</h2><p>${state.focus.active?'천천히 해도 괜찮아.':'쿠키가 옆에서 응원하고 있어요.'}</p></div><img src="public/assets/cookie-character.png" alt="제공된 쿠키 캐릭터 초안" /></section>
<div class="section-head"><h3>다음 일정</h3><button class="text-link" data-go="schedule">시간표 보기 ›</button></div>
${cls.length?cls.slice(0,2).map(c=>`<div class="card next-card" style="margin-bottom:9px"><div class="time-badge">${c.start}<small>수업 시작</small></div><div class="next-info"><strong>${esc(c.title)}</strong><small>${esc(c.room||'강의실 미정')}</small></div><span class="tiny-icon">⌁</span></div>`).join(''):`<div class="card free-card"><div><strong>오늘 등록된 수업이 없어요</strong><p>오늘은 나만의 속도로 보내도 좋아요.</p></div><span class="free-icon">☁</span></div>`}
<div class="section-head"><h3>오늘의 할 일</h3><button class="text-link" data-go="tasks">모두 보기 ›</button></div>
${list.length?`<div class="card">${list.map((t,i)=>`${i?'<div class="divider"></div>':''}<div class="task-row"><button class="check" data-done="${t.id}" aria-label="완료"></button><div class="task-text">${esc(t.title)}</div><span class="due">${remain(t.due)}</span></div>`).join('')}</div>`:`<div class="card empty">할 일을 모두 마쳤어요. 오늘 정말 잘했어요! 🍪</div>`}
<div class="section-head"><h3>틈새 시간</h3></div><div class="card free-card"><div><strong>${free}</strong><p>10분도 충분히 좋은 시간이 될 수 있어요.</p></div><span class="free-icon">☕</span></div>
<div class="section-head"><h3>빠른 메뉴</h3></div><div class="quick-grid"><button class="card quick-card" data-go="tasks"><span>✎</span><strong>할 일 추가하기</strong><small>시작 시간을 정해보세요</small></button><button class="card quick-card" data-go="focus"><span>◷</span><strong>집중 시작하기</strong><small>잠깐의 몰입부터</small></button></div>`}
function schedulePage(){const shift=new Date(today);shift.setDate(today.getDate()+weekOffset*7);const start=new Date(shift);start.setDate(shift.getDate()-shift.getDay());const days=Array.from({length:7},(_,i)=>new Date(start.getFullYear(),start.getMonth(),start.getDate()+i)),dayDate=days[selectedDay];const cls=state.classes.filter(c=>c.day===selectedDay).sort((a,b)=>a.start.localeCompare(b.start));let rows='';let prev='09:00';const minGap=Number(state.settings.gapMinutes??30);const addGap=(from,to)=>{const minutes=(new Date(`2000-01-01T${to}`)-new Date(`2000-01-01T${from}`))/60000;if(minutes<10)return '';const startAt=new Date(dayDate);startAt.setHours(+from.slice(0,2),+from.slice(3),0,0);const endAt=new Date(dayDate);endAt.setHours(+to.slice(0,2),+to.slice(3),0,0);const effectiveStart=new Date(Math.max(startAt.getTime(),Date.now()));const left=Math.floor((endAt-effectiveStart)/60000);if(left<10)return `<div class="free-slot"><span>☕ ${minutes>=minGap?'공강':'짧은 틈새'}</span><span>${from} — ${to}지난 시간</span></div>`;const size=left<30?'short':left<60?'medium':'long';const label=size==='short'?'짧은 공강복습/암기':size==='medium'?'중간 공강과제 일부 진행':'긴 공강과제 집중과 휴식';const task=nextSuggestedTask();const startValue=localDate(effectiveStart);const majorSuggestion=getMajorGapSuggestion(state.settings.major,size,localDate(dayDate));const activePlan=task?`${esc(task.title)}${task.priority==="높음"?"마감 우선":""}`:majorSuggestion.title;;const lengthText=left>=60?`${Math.floor(left/60)}시간 ${left%60?`${left%60}분`:''}`:`${left}분`;const acceptedTask=state.tasks.find(item=>!item.done&&item.start===startValue&&(item.id===task?.id||item.memo==='시간표 공강 추천으로 추가됨'));return `<div class="free-slot"><span>☕ ${minutes>=minGap?'공강':'짧은 틈새'}</span><span>${from} — ${to}&nbsp;${lengthText}</span></div><section class="recommend-card"><div class="recommend-heading"><span class="recommend-icon">✦</span><strong>${label}</strong></div><p>${task?`${activePlan}에 ${Math.min(left,Math.max(15,(task.hours||1)*30))}분 정도 써보세요.`:`${majorSuggestion.title} · ${majorSuggestion.detail}`} ${size==="long"?"중간에 짧은 휴식도 넣어보세요.":""}</p><small class="eyebrow">${task?"마감이 가까운 할 일을 우선 추천해요.":state.settings.major?`${esc(state.settings.major)} 계열 맞춤 예시 · 실제 이용자 통계는 아직 연결되지 않았어요.`:"설정에서 전공을 입력하면 전공 계열별 예시를 볼 수 있어요."}</small><button class="button secondary" data-gap-start="${startValue}" data-gap-end="${localDate(endAt)}" data-gap-task="${task?.id||''}" data-gap-size="${size}" ${acceptedTask?'disabled':''}>${acceptedTask?'시작 예약됨':'이 시간에 시작 예약'}</button></section>`};for(const c of cls){rows+=addGap(prev,c.start);rows+=`<div class="schedule-row"><div class="schedule-time">${c.start}</div><div class="schedule-block ${['','green','blue'][rows.length%3]}"><strong>${esc(c.title)}</strong><small>${c.start} — ${c.end}&nbsp;${esc(c.room||'강의실 미정')}</small><div class="class-actions"><button class="text-link" data-edit-class="${c.id}">수정</button><button class="text-link" data-delete-class="${c.id}">삭제</button></div></div></div>`;prev=c.end}rows+=addGap(prev,'18:00');
return `<div class="page-heading"><div><div class="eyebrow">나의 한 주</div><h1 class="page-title">시간표</h1></div><button class="button" data-modal="class">＋ 수업 추가</button></div><div class="week-switch"><button data-week="-1">‹</button><span>${days[0].getMonth()+1}월 ${days[0].getDate()}일 — ${days[6].getMonth()+1}월 ${days[6].getDate()}일</span><button data-week="1">›</button></div><div class="day-strip">${days.map((d,i)=>`<button class="day-chip ${selectedDay===i?'selected':''}" data-day="${i}">${weekdays[i]}<b>${d.getDate()}</b></button>`).join('')}</div><div class="section-head" style="margin-top:2px"><h3>${dayLabel(selectedDay)} 일정</h3><span class="eyebrow">${cls.length}개 수업</span></div>${cls.length?`<div class="schedule-list">${rows}</div>`:`<div class="card week-empty">아직 등록된 수업이 없어요.<br/>수업을 추가하면 공강 시간과 맞춤 제안을 함께 보여드릴게요.</div>`}<div class="notice">공강은 수업 사이 ${minGap}분 이상인 시간으로 표시돼요. 마감이 가까운 과제를 우선 제안하며, 수락하면 해당 시각의 시작 알림을 등록합니다.</div>`}
function tasksPage(){const list=sortedTasks();return `<div class="page-heading"><div><div class="eyebrow">차근차근 해내기</div><h1 class="page-title">나의 할 일</h1></div><button class="button" data-modal="task">＋ 추가</button></div><div class="stats-row"><div class="stat"><strong>${state.tasks.filter(x=>!x.done).length}</strong><small>남은 할 일</small></div><div class="stat"><strong>${state.tasks.filter(x=>x.done).length}</strong><small>완료한 일</small></div><div class="stat"><strong>${state.tasks.filter(x=>!x.done&&remain(x.due)==='오늘 마감').length}</strong><small>오늘 마감</small></div></div><div class="section-head"><h3>할 일 정렬</h3><select class="select sort-select" id="task-sort"><option value="due" ${state.settings.taskSort==='due'?'selected':''}>마감일 순</option><option value="priority" ${state.settings.taskSort==='priority'?'selected':''}>중요도 순</option></select></div><div class="task-list">${list.length?list.map(t=>`<div class="card task-card"><div class="task-top"><button class="check ${t.done?'done':''}" data-done="${t.id}">${t.done?'✓':''}</button><div class="task-text ${t.done?'done':''}">${esc(t.title)}</div>${t.priority==='높음'?'<span class="priority">중요</span>':''}<button class="text-link" data-task-menu="${t.id}" aria-label="할 일 메뉴">⋯</button></div><div class="task-meta"><span>마감 ${fmtDate(t.due)}</span><span>시작 ${fmtTime(t.start)}</span>${t.done?'':`<span>${remain(t.due)}</span>`}</div>${t.memo?`<div class="task-meta">${esc(t.memo)}</div>`:''}</div>`).join(''):`<div class="card empty">아직 할 일이 없어요. 작은 계획부터 추가해볼까요?</div>`}</div>`}
function focusPage(){const f=state.focus,session=Math.max(0,Number(f.sessionSeconds)||0),total=Math.max(0,Number(f.seconds)||0),rest=liveRestSeconds(),clock=value=>`${String(Math.floor(value/60)).padStart(2,'0')}:${String(value%60).padStart(2,'0')}`,nativeLogs=window.NativeMvp?.getDeviationCount?.()||0;return `<div class="eyebrow">휴대폰과 잠깐 거리 두기</div><h1 class="page-title">집중 시간</h1><p class="page-subtitle">잘하려고 애쓰지 않아도 괜찮아요. 지금 이 순간이면 충분해요.</p><div class="focus-hero"><img class="focus-character" src="public/assets/cookie-character.png" alt="제공된 쿠키 캐릭터 초안"/><div class="focus-clock-label">연속 집중 시간</div><div class="focus-timer ${f.deviation?'paused':''}" aria-label="연속 집중 시간">${clock(session)}</div><div class="focus-detail-row"><span>누적 집중 <strong class="focus-total-timer">${clock(total)}</strong></span><span id="focus-break-time">쉬는 시간 ${clock(rest)}${f.deviation?' · 휴식 중':' · 재개 시 00:00부터'}</span></div><p class="focus-state">${f.active?(f.deviation?'잠깐 쉬고 있어요':'쿠키와 함께 집중 중'):'준비가 되면 시작 버튼을 눌러주세요'}</p><div class="focus-controls">${f.active?`<button class="button ${f.deviation?'':'secondary'}" data-action="deviation">${f.deviation?'집중으로 돌아오기':'잠깐 쉬기'}</button><button class="button ghost" data-action="stop-focus">마치기</button>`:`<button class="button" data-action="start-focus">집중 시작하기</button>`}</div></div><div class="section-head"><h3>오늘의 작은 기록</h3></div><div class="stats-row"><div class="stat"><strong>${Math.floor(total/60)}분</strong><small>누적 집중 시간</small></div><div class="stat"><strong>${state.logs.length+nativeLogs}</strong><small>이탈 기록</small></div><div class="stat"><strong>${state.tasks.filter(t=>t.done).length}</strong><small>완료한 일</small></div></div><div class="notice">집중을 시작하면 선택한 앱을 확인하고, 화면 위 쿠키 알림과 진동으로 알려드려요. 이 기능은 Android 권한을 허용한 기기에서 동작합니다.</div>`}function gamePage(){return `<div class="eyebrow">잠깐 머리 깨우기</div><h1 class="page-title">인지 유연성 게임</h1><p class="page-subtitle">10초 안에 색깔 보석 5판을 모두 맞혀보세요.</p><section class="card"><strong>타임어택 · 5판</strong><p id="game-instruction">게임을 시작하면 맞힐 색깔이 표시돼요.</p><p id="game-feedback" class="game-feedback" aria-live="polite"></p><p id="game-timer" class="game-timer">제한 시간 10.0초</p><div class="progress-track game-time-track"><span id="game-time-progress" style="width:100%"></span></div><div class="mission-choices game-choices"><button class="button secondary" data-game-start>게임 시작</button><span id="game-result"></span></div><div id="game-board" class="game-board"></div></section>`}
function statsPage(){const now=new Date(),year=now.getFullYear(),month=now.getMonth(),first=new Date(year,month,1),offset=first.getDay(),daysInMonth=new Date(year,month+1,0).getDate(),qualifying=new Set((state.dailyRecords||[]).filter(dayQualifies).map(r=>r.date)),calendar=Array.from({length:offset},()=>'<span class="calendar-blank"></span>').concat(Array.from({length:daysInMonth},(_,i)=>{const date=new Date(year,month,i+1),key=dayKey(date),isToday=key===dayKey(),qualified=qualifying.has(key);return `<button class="calendar-day ${qualified?'qualified':''} ${isToday?'today':''}" data-record-date="${key}">${i+1}</button>`})).join(''),days=Array.from({length:7},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-6+i);const key=dayKey(d),seconds=recordedFocusSeconds(key),deviation=deviationSecondsFor(key),starts=(state.dailyRecords||[]).find(r=>r.date===key)?.onTimeStart?1:0;return {label:weekdays[d.getDay()],seconds,deviation,starts}}),maxSeconds=Math.max(60,...days.map(d=>d.seconds)),maxDeviation=Math.max(60,...days.map(d=>d.deviation)),totalMinutes=Math.floor((state.focus.seconds||0)/60),taskDone=state.tasks.filter(t=>t.done).length;return `<div class="eyebrow">쌓인 시간을 돌아봐요</div><h1 class="page-title">나의 기록</h1><p class="page-subtitle">꾸준히 이어온 하루를 스트릭 달력에서 확인해요.</p><div class="stats-row analytics-summary"><div class="stat"><strong>${state.streakCurrent||0}일</strong><small>현재 스트릭</small></div><div class="stat"><strong>${state.streakBest||0}일</strong><small>최고 스트릭</small></div><div class="stat"><strong>${totalMinutes}분</strong><small>누적 집중</small></div></div><div class="section-head"><h3>${year}년 ${month+1}월 스트릭 달력</h3></div><div class="card streak-calendar"><div class="calendar-week">${weekdays.map(d=>`<small>${d}</small>`).join('')}</div><div class="calendar-grid">${calendar}</div></div><div id="day-record-detail" class="notice">날짜를 눌러 원하는 날의 집중·과제 활동 요약을 확인하세요.</div><div class="section-head"><h3>최근 7일 집중 시간</h3></div><div class="card weekly-chart">${days.map(d=>`<div class="chart-column"><strong>${Math.floor(d.seconds/60)}분</strong><div class="chart-track"><span style="height:${Math.max(d.seconds?5:0,Math.round(d.seconds/maxSeconds*100))}%"></span></div><small>${d.label}</small></div>`).join('')}</div><div class="section-head"><h3>최근 7일 앱 이탈 시간</h3></div><div class="card weekly-chart task-chart">${days.map(d=>`<div class="chart-column"><strong>${Math.floor(d.deviation/60)}분</strong><div class="chart-track"><span style="height:${d.deviation?Math.max(5,Math.round(d.deviation/maxDeviation*100)):0}%"></span></div><small>${d.label}</small></div>`).join('')}</div><div class="section-head"><h3>앱별 이탈 기록최근 7일</h3></div><div class="card">${appDeviationSummary(days)||'<p class="eyebrow">아직 기록이 없어요.</p>'}</div><div class="notice">기록은 이 기기에 저장됩니다. 과거 앱 사용 정보와 시작 시간 준수율은 해당 기능이 켜진 뒤부터 집계돼요.</div>`}
function appDeviationSummary(days){const keys=new Set(Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-i);return dayKey(d)})),totals={};for(const log of state.logs||[]){if(!keys.has(dayKey(new Date(log.start))))continue;const seconds=Number(log.duration||((log.end&&log.start)?Math.round((log.end-log.start)/1000):log.start?Math.floor((Date.now()-log.start)/1000):0));totals[log.app||'기타']=(totals[log.app||'기타']||0)+seconds}return Object.entries(totals).sort((a,b)=>b[1]-a[1]).map(([app,seconds])=>`<div class="setting-row"><span>${esc(app)}</span><strong>${Math.floor(seconds/60)}분</strong></div><div class="divider"></div>`).join('')}
function settingsPage(){
  const permissions=[['usage','앱 사용 기록 접근','금지 앱 감지에 필요해요',window.NativeMvp?.hasUsageAccess?.()],['overlay','다른 앱 위에 표시','쿠키 오버레이에 필요해요',window.NativeMvp?.hasOverlayPermission?.()],['notification','알림 권한','과제 시작 예고를 받아요',window.NativeMvp?.hasNotificationPermission?.()],['exactAlarm','정확한 알람','앱이 닫혀 있을 때도 예고해요',window.NativeMvp?.hasExactAlarmPermission?.()]];
  const blocked=state.blocked.map(a=>esc(window.NativeMvp?.appLabel?.(a)||a)).join('');
  return `<div class="eyebrow">나에게 맞게 설정하기</div><h1 class="page-title">설정</h1><p class="page-subtitle">편안한 방식으로 조절해보세요.</p>
  <div class="section-head"><h3>알림과 캐릭터</h3></div><div class="settings-list card">${[['countdown','시작 전 카운트다운','시작 예고를 받아요'],['reminder','과제 마감 알림','마감 전 알림을 받아요'],['character','캐릭터 말풍선','캐릭터가 응원 메시지를 보내요'],['vibration','오래 머물면 진동','이탈이 길어질 때 알려드려요']].map(([k,a,b])=>`<div class="setting-row"><div><strong>${a}</strong><p>${b}</p></div><button class="switch ${state.settings[k]?'on':''}" data-setting="${k}" aria-label="${a} 토글"></button></div>`).join('')}</div>
  <div class="section-head"><h3>알림 세부 설정</h3></div><div class="card settings-list"><div class="setting-row"><div><strong>과제 시작 예고</strong><p>원하는 예고 시점을 선택하세요</p></div><div class="choice-row">${[10,5,3,1].map(n=>`<label><input type="checkbox" data-countdown-lead="${n}" ${state.settings.countdownLeads.includes(n)?'checked':''}/> ${n}분</label>`).join('')}</div></div><div class="divider"></div><div class="setting-row"><div><strong>마감 알림</strong><p>마감 전에 알려드려요</p></div><div class="choice-row"><label><input type="checkbox" data-reminder="24" ${state.settings.reminder24h?'checked':''}/> 1일 전</label><label><input type="checkbox" data-reminder="3" ${state.settings.reminder3h?'checked':''}/> 3시간 전</label></div></div><div class="notice">마감 알림은 마감 시각 기준으로 예약돼요. Android에서는 앱을 닫아도 시스템 알림으로 전달됩니다.</div></div>
  <div class="section-head"><h3>시간표 설정</h3></div><div class="card settings-list"><label class="field-label" for="gap-minutes">공강으로 표시할 최소 시간</label><div class="setting-control"><input class="input compact-input" id="gap-minutes" type="number" min="0" max="240" step="5" value="${state.settings.gapMinutes}"/><span>분 이상</span></div></div>
  <div class="section-head"><h3>전공 맞춤 공강 추천</h3></div><div class="card settings-list"><label class="field-label" for="major-input">전공</label><input class="input" id="major-input" type="text" maxlength="40" placeholder="예: 컴퓨터공학과" value="${esc(state.settings.major||'')}"/><p class="page-subtitle">전공 계열별 활동 예시를 공강 추천에 반영해요. 현재는 실제 이용자 통계가 아닌 기본 예시입니다.</p><button class="button secondary" id="save-major">전공 저장</button></div>
  <div class="section-head"><h3>캐릭터 말풍선</h3></div><div class="card settings-list"><label class="field-label" for="bubble-frequency">집중 중 응원 메시지 빈도</label><select class="select" id="bubble-frequency"><option value="5" ${state.settings.bubbleIntervalMinutes===5?'selected':''}>5분마다</option><option value="15" ${state.settings.bubbleIntervalMinutes===15?'selected':''}>15분마다</option><option value="30" ${state.settings.bubbleIntervalMinutes===30?'selected':''}>30분마다</option></select><small class="eyebrow">말풍선 표시를 끄면 캐릭터와 응원 메시지가 숨겨져요.</small></div>
  <div class="section-head"><h3>진동 세부 설정</h3></div><div class="card settings-list"><p class="page-subtitle">이탈이 길어질수록 진동 단계를 높여요.</p><div class="threshold-grid">${state.settings.vibrationThresholds.map((n,i)=>`<label class="field-label">${i+1}단계<input class="input" type="number" min="1" max="180" data-vibration-threshold="${i}" value="${n}"/><small>분</small></label>`).join('')}</div><label class="field-label" for="vibration-intensity">진동 강도</label><select class="select" id="vibration-intensity"><option value="1" ${state.settings.vibrationIntensity===1?'selected':''}>약하게</option><option value="2" ${state.settings.vibrationIntensity===2?'selected':''}>보통</option><option value="3" ${state.settings.vibrationIntensity===3?'selected':''}>강하게</option></select><label class="field-label" for="vibration-dnd">방해금지 모드</label><select class="select" id="vibration-dnd"><option value="respect" ${state.settings.vibrationDnd==='respect'?'selected':''}>기기 설정 따르기</option><option value="attempt" ${state.settings.vibrationDnd==='attempt'?'selected':''}>진동 시도</option></select><p class="notice">방해금지 모드 중 진동 여부는 Android의 기기 설정과 제조사 정책에 따라 달라질 수 있어요.</p></div>
  <div class="section-head"><h3>집중을 방해하는 앱</h3><button class="text-link" data-modal="apps">변경 ›</button></div><div class="card">${blocked||'<span class="eyebrow">아직 선택한 앱이 없어요</span>'}<div class="notice" style="margin-bottom:0">선택한 앱을 감지해 화면 위 쿠키 알림과 진동을 보여드려요.</div><label class="field-label" for="blocked-mode">금지 앱 감지 기준</label><select class="select" id="blocked-mode"><option value="focus" ${state.settings.blockedMode==='focus'?'selected':''}>집중 세션 중</option><option value="always" ${state.settings.blockedMode==='always'?'selected':''}>항상</option><option value="schedule" ${state.settings.blockedMode==='schedule'?'selected':''}>요일·시간 지정</option></select>${state.settings.blockedMode==='schedule'?`<div class="choice-row" style="margin:12px 0">${weekdays.map((d,i)=>`<label><input type="checkbox" data-blocked-day="${i}" ${state.settings.blockedDays.includes(i)?'checked':''}/> ${d}</label>`).join('')}</div><div class="form-grid"><label class="field-label">시작<input class="input" type="time" id="blocked-start" value="${state.settings.blockedStart}"/></label><label class="field-label">종료<input class="input" type="time" id="blocked-end" value="${state.settings.blockedEnd}"/></label></div>`:''}<p class="eyebrow">‘항상’과 예약 감지는 Android에서 앱 사용 기록·오버레이 권한을 허용해야 하며 백그라운드 감시 알림이 표시됩니다.</p></div>
  <div class="section-head"><h3>Android 권한</h3></div><div class="card settings-list">${permissions.map(([key,label,help,granted])=>`<div class="setting-row"><div><strong>${label}</strong><p>${help}</p></div><button class="button secondary" data-permission="${key}">${granted===true?'허용됨':granted===false?'허용 필요':'확인 불가'}</button></div><div class="divider"></div>`).join('')}</div><button class="text-link" data-onboarding="reset">권한 안내 다시 보기</button><p class="eyebrow" style="text-align:center;margin:22px 0">CookieTime MVP기기 내 저장</p>`
}
function bindCommon(){document.querySelector("#save-major")?.addEventListener("click",()=>{state.settings.major=document.querySelector("#major-input")?.value.trim()||"";save();render();showToast(state.settings.major?"전공을 저장했어요.":"전공 입력을 지웠어요.")});document.querySelectorAll('[data-game-start]').forEach(b=>b.onclick=()=>startExecutiveGame());document.querySelectorAll('[data-task-menu]').forEach(b=>b.onclick=()=>openTaskMenu(b.dataset.taskMenu));document.querySelectorAll("[data-onboarding]").forEach(b=>b.onclick=()=>{const a=b.dataset.onboarding;if(a==="reset"){state.settings.onboardingDone=false;save();render();return}state.settings.onboardingDone=true;save();if(a==="settings"){page="settings";render()}else{page="home";render()}});document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-modal]').forEach(b=>b.onclick=()=>b.dataset.modal==='apps'?openAppsModal():openModal(b.dataset.modal));document.querySelectorAll('[data-done]').forEach(b=>b.onclick=()=>toggleTask(b.dataset.done));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{state.tasks=state.tasks.filter(t=>t.id!==b.dataset.delete);save();render();showToast('할 일을 삭제했어요')});document.querySelectorAll('[data-delete-class]').forEach(b=>b.onclick=()=>{state.classes=state.classes.filter(c=>c.id!==b.dataset.deleteClass);save();render();showToast('수업을 삭제했어요')});document.querySelectorAll('[data-edit-class]').forEach(b=>b.onclick=()=>openModal('class',b.dataset.editClass));document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{selectedDay=+b.dataset.day;render()});document.querySelectorAll('[data-week]').forEach(b=>b.onclick=()=>{weekOffset+=+b.dataset.week;const d=new Date(today);d.setDate(today.getDate()+weekOffset*7);selectedDay=d.getDay();render()});document.querySelectorAll('[data-setting]').forEach(b=>b.onclick=()=>{state.settings[b.dataset.setting]=!state.settings[b.dataset.setting];save();render()});document.querySelectorAll('[data-countdown-lead]').forEach(b=>b.onchange=()=>{state.settings.countdownLeads=[...document.querySelectorAll('[data-countdown-lead]:checked')].map(x=>Number(x.dataset.countdownLead)).sort((a,b)=>b-a);save()});document.querySelectorAll('[data-reminder]').forEach(b=>b.onchange=()=>{state.settings[b.dataset.reminder==='24'?'reminder24h':'reminder3h']=b.checked;save()});document.querySelectorAll('[data-vibration-threshold]').forEach(b=>b.onchange=()=>{const values=[...document.querySelectorAll('[data-vibration-threshold]')].map(x=>Number(x.value));if(values.some(x=>!Number.isFinite(x)||x<1)||values[0]>=values[1]||values[1]>=values[2]){showToast('진동 단계는 1단계부터 순서대로 더 큰 값을 입력해주세요.');render();return}state.settings.vibrationThresholds=values;save()});document.querySelector('#blocked-mode')?.addEventListener('change',e=>{state.settings.blockedMode=e.target.value;save();render()});document.querySelectorAll('[data-blocked-day]').forEach(x=>x.onchange=()=>{state.settings.blockedDays=[...document.querySelectorAll('[data-blocked-day]:checked')].map(y=>Number(y.dataset.blockedDay));save()});document.querySelector('#blocked-start')?.addEventListener('change',e=>{state.settings.blockedStart=e.target.value;save()});document.querySelector('#blocked-end')?.addEventListener('change',e=>{state.settings.blockedEnd=e.target.value;save()});document.querySelector('#gap-minutes')?.addEventListener('change',e=>{state.settings.gapMinutes=Math.max(0,Math.min(240,Number(e.target.value)||0));save();render()});document.querySelector('#task-sort')?.addEventListener('change',e=>{state.settings.taskSort=e.target.value;save();render()});document.querySelector('#vibration-intensity')?.addEventListener('change',e=>{state.settings.vibrationIntensity=Number(e.target.value);save()});document.querySelector('#vibration-dnd')?.addEventListener('change',e=>{state.settings.vibrationDnd=e.target.value;save()});document.querySelectorAll('[data-permission]').forEach(b=>b.onclick=()=>{if(window.NativeMvp?.requestPermission){window.NativeMvp.requestPermission(b.dataset.permission);setTimeout(()=>page==='settings'&&render(),650)}else showToast('Android 앱에서 권한을 연결할 수 있어요')});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>focusAction(b.dataset.action));}
function toggleTask(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;t.done=!t.done;t.doneAt=t.done?Date.now():null;if(t.done){dailyRecord().taskCompletions++;updateStreaks()}save();render();showToast(t.done?'잘했어요! 하나 해냈어요.':'완료를 취소했어요')}
function finishBreak(f){if(!f.deviation)return;const end=Date.now(),duration=Math.max(0,Math.round((end-(f.deviationAt||end))/1000)),log=state.logs.find(item=>item.id===f.activeDeviationLogId);if(log){log.end=end;log.duration=duration}f.restSeconds=(f.restSeconds||0)+duration;f.deviation=false;f.deviationAt=null;f.activeDeviationLogId=null}
function focusAction(action){const f=state.focus;if(action==='start-focus'){if(!f.active){f.deviationAt=null;f.activeDeviationLogId=null;f.sessionSeconds=0;f.rewardedHours=0;f.gapFocusSeconds=0;f.rewardedGapHours=0;f.sessionStartedAt=Date.now();f.speechAt=Date.now();f.speech='천천히 시작해도 괜찮아요!'}f.active=true;f.deviation=false;const ready=window.NativeMvp?.startMonitoring?.();showToast(ready===false?'사용 기록과 화면 위 표시 권한을 허용하면 앱 감지를 시작해요.':'집중 세션을 시작했어요. 응원할게요!')}else if(action==='deviation'){f.deviation=!f.deviation;if(f.deviation){f.deviationAt=Date.now();f.vibrationStage=0;if(state.settings.vibration){navigator.vibrate?.([80,60,80]);window.NativeMvp?.vibrate?.(180)}const log={id:crypto.randomUUID(),app:'선택한 앱',start:Date.now()};state.logs.push(log);f.activeDeviationLogId=log.id;showToast('잠깐 쉬어도 괜찮아요. 준비되면 돌아와요.')}else{finishBreak(f);showToast('돌아온 걸 환영해요!')} }else if(action==='stop-focus'){finishBreak(f);if(f.sessionSeconds>0){state.focusSessions=state.focusSessions||[];state.focusSessions.push({id:crypto.randomUUID(),start:f.sessionStartedAt||Date.now()-f.sessionSeconds*1000,end:Date.now(),seconds:f.sessionSeconds});state.focusSessions=state.focusSessions.slice(-500)}f.active=false;f.sessionStartedAt=null;window.NativeMvp?.stopMonitoring?.();showToast('집중 세션을 마쳤어요. 수고했어요!')}pulse.lastAt=Date.now();save();render()}
function snoozeTask(id){const task=state.tasks.find(t=>t.id===id);if(!task||task.done)return;if((task.snoozes||0)>=2){showToast('미루기는 최대 2회까지 할 수 있어요.');return}task.snoozes=(task.snoozes||0)+1;task.start=localDate(new Date(Date.now()+5*60000));for(let i=sessionStorage.length-1;i>=0;i--){const key=sessionStorage.key(i);if(key?.startsWith(`${task.id}-`))sessionStorage.removeItem(key)}save();document.querySelector('#modal-root').innerHTML='';showToast('5분 뒤 다시 알려드릴게요.');}
function vibrateStage(stage){if(!state.settings.vibration||stage<1)return;const scale=[0,.65,1,1.45][Math.max(1,Math.min(3,Number(state.settings.vibrationIntensity)||1))],pattern=stage===1?[80]:stage===2?[100,70,100]:[130,60,130,60,130];const adjusted=pattern.map((n,i)=>i%2===0?Math.round(n*scale):n);navigator.vibrate?.(adjusted);window.NativeMvp?.vibrate?.(adjusted.filter((_,i)=>i%2===0).reduce((a,b)=>a+b,0))}
function promptTaskStart(id){const task=state.tasks.find(t=>t.id===id);if(!task)return;const root=document.querySelector('#modal-root');const canSnooze=(task.snoozes||0)<2;root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><h2>시작할 시간이에요</h2><button class="close" data-close aria-label="닫기">×</button></div><p class="page-subtitle">${esc(task.title)}를 지금 시작해볼까요?</p><div class="modal-actions"><button class="button" data-start-now>집중 시작</button>${canSnooze?'<button class="button secondary" data-snooze="'+task.id+'">5분만 더</button>':''}</div></section></div>`;root.querySelector('[data-close]').onclick=()=>root.innerHTML='';root.querySelector('[data-start-now]').onclick=()=>{root.innerHTML='';if(!state.focus.active){const rewarded=awardOnTimeStart(task);focusAction('start-focus');if(rewarded)showToast('정시에 시작했어요. 오늘 기록에 반영했어요.')}else showToast('이미 집중 세션이 진행 중이에요')};root.querySelector('[data-snooze]')?.addEventListener('click',()=>snoozeTask(task.id))}
window.startFocusFromNotification=()=>{if(!state.focus.active)focusAction('start-focus');else{go('focus');showToast('이미 집중 세션이 진행 중이에요')}};
function openTaskMenu(id){const task=state.tasks.find(t=>t.id===id);if(!task)return;const root=document.querySelector('#modal-root');root.innerHTML='<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><h2>할 일 관리</h2><button class="close" data-close aria-label="닫기">×</button></div><div class="settings-list"><button class="button secondary full" data-task-edit>수정</button><button class="button secondary full" data-task-memo>메모 추가</button><button class="button ghost full" data-task-delete>삭제</button></div></section></div>';root.querySelector('[data-close]').onclick=()=>root.innerHTML='';root.querySelector('[data-task-edit]').onclick=()=>{root.innerHTML='';openTaskEditModal(id)};root.querySelector('[data-task-memo]').onclick=()=>{root.innerHTML='';openTaskMemoModal(id)};root.querySelector('[data-task-delete]').onclick=()=>{if(confirm('이 할 일을 삭제할까요?')){state.tasks=state.tasks.filter(t=>t.id!==id);save();root.innerHTML='';render();showToast('할 일을 삭제했어요')}}}
function openTaskEditModal(id){const task=state.tasks.find(t=>t.id===id);if(!task)return;const root=document.querySelector('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><h2>할 일 수정</h2><button class="close" data-close aria-label="닫기">×</button></div><form id="task-edit-form"><label class="field-label">과제명</label><input class="input" name="title" required maxlength="50" value="${esc(task.title)}"/><div class="form-grid"><div><label class="field-label">마감일시</label><input class="input" name="due" type="datetime-local" required value="${esc(task.due)}"/></div><div><label class="field-label">시작 예정</label><input class="input" name="start" type="datetime-local" required value="${esc(task.start)}"/></div></div><div class="form-grid"><div><label class="field-label">예상 소요 시간</label><select class="select" name="hours"><option value="0.5" ${task.hours===0.5?'selected':''}>30분</option><option value="1" ${task.hours===1?'selected':''}>1시간</option><option value="2" ${task.hours===2?'selected':''}>2시간</option><option value="3" ${task.hours>=3?'selected':''}>3시간 이상</option></select></div><div><label class="field-label">중요도</label><select class="select" name="priority"><option ${task.priority==='보통'?'selected':''}>보통</option><option ${task.priority==='높음'?'selected':''}>높음</option></select></div></div><label class="field-label">메모</label><textarea class="textarea" name="memo">${esc(task.memo||'')}</textarea><div class="modal-actions"><button type="button" class="button ghost" data-close>취소</button><button class="button" type="submit">수정 저장</button></div></form></section></div>`;root.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelector('#task-edit-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.currentTarget);Object.assign(task,{title:d.get('title').trim(),due:d.get('due'),start:d.get('start'),hours:Number(d.get('hours')),priority:d.get('priority'),memo:d.get('memo').trim()});save();root.innerHTML='';render();showToast('할 일을 수정했어요')}}
function openTaskMemoModal(id){const task=state.tasks.find(t=>t.id===id);if(!task)return;const root=document.querySelector('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><h2>메모 추가</h2><button class="close" data-close aria-label="닫기">×</button></div><form id="task-memo-form"><label class="field-label">${esc(task.title)}</label><textarea class="textarea" name="memo" maxlength="500" placeholder="할 일에 필요한 메모를 적어두세요">${esc(task.memo||'')}</textarea><div class="modal-actions"><button type="button" class="button ghost" data-close>취소</button><button class="button" type="submit">메모 저장</button></div></form></section></div>`;root.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelector('#task-memo-form').onsubmit=e=>{e.preventDefault();task.memo=new FormData(e.currentTarget).get('memo').trim();save();root.innerHTML='';render();showToast('메모를 저장했어요')}}
function openAppsModal(){const root=document.querySelector('#modal-root');const labels=['Instagram','YouTube','TikTok','X','Netflix'];let apps=labels.map(label=>({label,value:label}));try{const installed=JSON.parse(window.NativeMvp?.installedAppsJson?.()||'[]');if(installed.length)apps=installed.map(a=>({label:a.label,value:a.label}))}catch{}const selected=new Set(state.blocked);const body=`<p class="page-subtitle">휴대폰에 설치된 앱 중 잠깐 멀리하고 싶은 앱을 골라주세요.</p><div style="margin-top:13px;max-height:45vh;overflow:auto">${apps.map(a=>`<div class="app-chip"><label><input type="checkbox" name="blocked" value="${esc(a.value)}" ${selected.has(a.value)?'checked':''}/>${esc(a.label)}</label><span class="eyebrow">앱</span></div>`).join('')}</div><div class="notice">앱 사용 기록 권한을 허용한 뒤 집중을 시작하면 선택한 앱을 감지합니다.</div><button class="button full" id="save-apps">선택 저장</button>`;root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><h2>집중 방해 앱 선택</h2><button class="close" data-close aria-label="닫기">×</button></div>${body}</section></div>`;root.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelector('#save-apps').onclick=()=>{state.blocked=[...root.querySelectorAll('[name=blocked]:checked')].map(i=>i.value);save();root.innerHTML='';render();showToast('집중 방해 앱을 저장했어요')}}
function openModal(type,editId=null){const root=document.querySelector('#modal-root');let body='',title='';if(type==='task'){title='할 일 추가';body=`<form id="task-form"><label class="field-label">과제명</label><input class="input" name="title" required maxlength="50" placeholder="예: 발표 자료 초안 만들기"/><div class="form-grid"><div><label class="field-label">마감일시</label><input class="input" name="due" type="datetime-local" required value="${localDate(new Date(today.getFullYear(),today.getMonth(),today.getDate()+1,18,0))}"/></div><div><label class="field-label">시작 예정</label><input class="input" name="start" type="datetime-local" required value="${localDate(new Date(today.getFullYear(),today.getMonth(),today.getDate(),new Date().getHours()+1,0))}"/></div></div><div class="form-grid"><div><label class="field-label">예상 소요 시간</label><select class="select" name="hours"><option value="0.5">30분</option><option value="1" selected>1시간</option><option value="2">2시간</option><option value="3">3시간 이상</option></select></div><div><label class="field-label">중요도</label><select class="select" name="priority"><option>보통</option><option>높음</option></select></div></div><label class="field-label">메모 (선택)</label><textarea class="textarea" name="memo" placeholder="잊지 않도록 짧게 적어두세요"></textarea><div class="notice">시작 시간이 다가오면 카운트다운 알림을 보여드려요.</div><button class="button full" type="submit">할 일 저장하기</button></form>`}else if(type==='class'){const current=state.classes.find(c=>c.id===editId);title=current?'수업 수정':'수업 추가';body=`<form id="class-form"><label class="field-label">과목명</label><input class="input" name="title" required value="${esc(current?.title||'')}" placeholder="예: 미디어와 사회"/><label class="field-label">요일</label><select class="select" name="day">${weekdays.map((d,i)=>`<option value="${i}" ${(current?.day??selectedDay)===i?'selected':''}>${dayLabel(i)}</option>`).join('')}</select><div class="form-grid"><div><label class="field-label">시작 시간</label><input class="input" name="start" type="time" value="${current?.start||'09:00'}" required/></div><div><label class="field-label">종료 시간</label><input class="input" name="end" type="time" value="${current?.end||'10:30'}" required/></div></div><label class="field-label">강의실 (선택)</label><input class="input" name="room" value="${esc(current?.room||'')}" placeholder="예: 인문관 302"/><div class="modal-actions"><button type="button" class="button ghost" data-close>취소</button><button class="button" type="submit">${current?'수정 저장':'시간표 저장'}</button></div></form>`}else{title='집중 방해 앱 선택';const apps=['Instagram','YouTube','TikTok','X','Netflix','게임 앱'];body=`<p class="page-subtitle">잠깐 멀리하고 싶은 앱을 골라주세요.</p><div style="margin-top:13px">${apps.map(a=>`<div class="app-chip"><label><input type="checkbox" name="blocked" value="${a}" ${state.blocked.includes(a)?'checked':''}/>${a}</label><span class="eyebrow">앱</span></div>`).join('')}</div><div class="notice">실제 설치 앱 목록은 Android 권한을 연결한 뒤 불러올 수 있어요.</div><button class="button full" id="save-apps">선택 저장</button>`}
root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><h2>${title}</h2><button class="close" data-close aria-label="닫기">×</button></div>${body}</section></div>`;root.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''};
const tf=root.querySelector('#task-form');if(tf)tf.onsubmit=e=>{e.preventDefault();const d=new FormData(tf);state.tasks.push({id:crypto.randomUUID(),title:d.get('title').trim(),due:d.get('due'),start:d.get('start'),hours:+d.get('hours'),priority:d.get('priority'),memo:d.get('memo').trim(),done:false,snoozes:0});save();root.innerHTML='';go('tasks');showToast('할 일을 저장했어요')};const cf=root.querySelector('#class-form');if(cf)cf.onsubmit=e=>{e.preventDefault();const d=new FormData(cf);if(d.get('start')>=d.get('end')){showToast('종료 시간을 시작 시간 뒤로 설정해주세요');return}const day=+d.get('day'),start=d.get('start'),end=d.get('end'),collision=state.classes.find(c=>c.id!==editId&&c.day===day&&c.start<end&&c.end>start);if(collision){showToast(`'${collision.title}' 수업과 시간이 겹쳐요.`);return}const entry={id:editId||crypto.randomUUID(),day,start,end,title:d.get('title').trim(),room:d.get('room').trim()},idx=state.classes.findIndex(c=>c.id===editId);if(idx>=0)state.classes[idx]=entry;else state.classes.push(entry);save();selectedDay=day;root.innerHTML='';go('schedule');showToast(editId?'수업을 수정했어요':'시간표에 저장했어요')};const ab=root.querySelector('#save-apps');if(ab)ab.onclick=()=>{state.blocked=[...root.querySelectorAll('[name=blocked]:checked')].map(i=>i.value);save();root.innerHTML='';render();showToast('집중 방해 앱을 저장했어요')}}
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));document.querySelector('#settings-shortcut').onclick=()=>go('settings');document.querySelector('#account-shortcut').onclick=openAccountModal;renderAccountButton();document.addEventListener('cookietime-auth-change',event=>{authUser=event.detail?.user||null;renderAccountButton();if(document.querySelector('#account-modal'))openAccountModal()});document.addEventListener('click',event=>{if(event.target.closest('[data-open-account]')){openAccountModal();return}const button=event.target.closest('[data-gap-start]');if(!button)return;const startAt=new Date(button.dataset.gapStart),endAt=new Date(button.dataset.gapEnd);if(startAt<new Date())startAt.setTime(Date.now()+1000);if(startAt>=endAt){showToast('이미 지난 공강이라 시작 시간을 예약할 수 없어요.');return}const size=button.dataset.gapSize;let task=state.tasks.find(item=>item.id===button.dataset.gapTask&&!item.done);if(!task)task=state.tasks.find(item=>!item.done&&item.memo==='시간표 공강 추천으로 추가됨'&&item.start===localDate(startAt));if(!task){const title=size==='short'?'수업 핵심 내용 복습':size==='medium'?'공강 과제 정리':'공강 집중 시간',due=new Date(startAt);due.setHours(23,59,0,0);task={id:crypto.randomUUID(),title,due:localDate(due),start:localDate(startAt),hours:Math.max(.5,Math.round(((endAt-startAt)/3600000)*2)/2),priority:'보통',memo:'시간표 공강 추천으로 추가됨',done:false,snoozes:0};state.tasks.push(task)}else task.start=localDate(startAt);save();showToast(`${task.title} 시작 알림을 ${fmtTime(task.start)}에 예약했어요`);render()});
function pulse(){const tickNow=Date.now();if(resetDailyFocusIfNeeded(tickNow)){save();if(page==='focus')render()}if(!Number.isFinite(pulse.lastAt))pulse.lastAt=tickNow;const elapsed=Math.max(0,Math.floor((tickNow-pulse.lastAt)/1000));if(elapsed>0)pulse.lastAt+=elapsed*1000;if(state.focus.active&&elapsed>0){const f=state.focus,rewards=state.cookieRewards,beforeTotal=rewards.loose+rewards.boxes*10;if(!f.deviation){const previousSession=Number(f.sessionSeconds)||0,daySeconds=addFocusSecondsAcrossDays(pulse.lastAt-elapsed*1000,elapsed);f.seconds=(Number(f.seconds)||0)+daySeconds;f.sessionSeconds=previousSession+elapsed;if(isCurrentClassGap()&&previousSession<5*3600)f.gapFocusSeconds=(Number(f.gapFocusSeconds)||0)+Math.min(elapsed,5*3600-previousSession);grantFocusCookieRewards()}if(f.deviation&&state.settings.vibration&&Array.isArray(state.settings.vibrationThresholds)){const spent=(tickNow-(f.deviationAt||tickNow))/60000,stage=state.settings.vibrationThresholds.reduce((n,threshold,i)=>spent>=threshold?i+1:n,0);if(stage>f.vibrationStage){f.vibrationStage=stage;vibrateStage(stage)}}save();if(page==='focus'){const afterTotal=rewards.loose+rewards.boxes*10;if(afterTotal!==beforeTotal){render()}else if(f.deviation){const breakTimer=document.querySelector('#focus-break-time');if(breakTimer){const rest=liveRestSeconds(),m=String(Math.floor(rest/60)).padStart(2,'0'),sec=String(rest%60).padStart(2,'0');breakTimer.textContent='쉬는 시간 '+m+':'+sec+' · 휴식 중'}}else{const focusTimer=document.querySelector('.focus-timer');if(focusTimer&&!document.querySelector('.bake-page')){const m=String(Math.floor(f.sessionSeconds/60)).padStart(2,'0'),sec=String(f.sessionSeconds%60).padStart(2,'0');focusTimer.textContent=m+':'+sec;focusTimer.setAttribute('aria-label','연속 집중 시간')}}const totalTimer=document.querySelector('.focus-total-timer');if(totalTimer&&!f.deviation){const m=String(Math.floor(f.seconds/60)).padStart(2,'0'),sec=String(f.seconds%60).padStart(2,'0');totalTimer.textContent=m+':'+sec}const focusStat=document.querySelector('.stats-row .stat strong');if(focusStat&&!f.deviation)focusStat.textContent=Math.floor(f.seconds/60)+'분'}}const now=new Date();for(const t of state.tasks){if(t.done)continue;if(t.start&&state.settings.countdown){const delta=new Date(t.start)-now,mins=Math.round(delta/60000),leads=[...new Set([...(state.settings.countdownLeads||[10,5,3,1]),0])];if(leads.includes(mins)&&delta>=0&&delta<59000){const marker=`${t.id}-start-${mins}`;if(!sessionStorage.getItem(marker)){sessionStorage.setItem(marker,'1');if(mins===0){promptTaskStart(t.id);window.NativeMvp?.countdown?.(t.title,0,t.id,t.snoozes||0)}else{showToast(`${mins}분 뒤 시작해요${t.title}`);window.NativeMvp?.countdown?.(t.title,mins,t.id,t.snoozes||0)}}}}if(state.settings.reminder){const dueDelta=new Date(t.due)-now;for(const mins of [1440,180]){const enabled=mins===1440?state.settings.reminder24h:state.settings.reminder3h;if(!enabled)continue;const remaining=Math.round(dueDelta/60000);if(remaining===mins&&dueDelta>=0&&dueDelta<59000){const marker=`${t.id}-due-${mins}`;if(!sessionStorage.getItem(marker)){sessionStorage.setItem(marker,'1');showToast(`${mins===1440?'하루':'3시간'} 뒤 마감이에요${t.title}`)}}}}}}
window.refreshNativeSettings=()=>{if(page==='settings'||page==='focus')render();if((state.focus.active||state.settings.blockedMode!=='focus')&&window.NativeMvp?.hasUsageAccess?.()&&window.NativeMvp?.hasOverlayPermission?.())window.NativeMvp.startMonitoring()};updateStreaks();save();timer=setInterval(pulse,1000);render();syncNativeState();

document.addEventListener('change',event=>{if(event.target.id==='bubble-frequency'){state.settings.bubbleIntervalMinutes=Number(event.target.value);save();showToast('말풍선 빈도를 저장했어요')}if(event.target.id==='streak-criterion'){state.settings.streakCriterion=event.target.value;updateStreaks();save();render()}if(event.target.id==='deviation-goal'){state.settings.dailyDeviationGoalMinutes=Number(event.target.value)||60;updateStreaks();save();render()}if(event.target.id==='usage-default'){state.settings.usageDefaultMinutes=Number(event.target.value)||15;save()}});
document.addEventListener('click',event=>{if(event.target.closest('[data-cookie-share]')){shareCookieCollection();return}const day=event.target.closest('[data-record-date]');if(day){const key=day.dataset.recordDate,record=(state.dailyRecords||[]).find(r=>r.date===key),detail=document.querySelector('#day-record-detail');if(detail)detail.textContent=`${key} 활동 요약 · 집중 ${Math.floor(recordedFocusSeconds(key)/60)}분 · 예정 시각 ±5분 내 시작 ${record?.onTimeStarts||0}/${record?.scheduledStarts||0}회 · 앱 이탈 ${Math.floor(deviationSecondsFor(key)/60)}분 · 완료한 할 일 ${record?.taskCompletions||0}개`;return}});
function startExecutiveGame(){clearInterval(executiveTicker);executiveGame={stage:1,score:0,rule:'color',startedAt:performance.now(),duration:10000};document.querySelector('#game-result').textContent='';updateExecutiveTimer();playExecutiveStage();executiveTicker=setInterval(updateExecutiveTimer,50)}function updateExecutiveTimer(){if(!executiveGame)return;const elapsed=performance.now()-executiveGame.startedAt,remaining=Math.max(0,executiveGame.duration-elapsed),timer=document.querySelector('#game-timer'),bar=document.querySelector('#game-time-progress');if(timer)timer.textContent=`남은 시간 ${(remaining/1000).toFixed(1)}초`;if(bar)bar.style.width=`${remaining/executiveGame.duration*100}%`;if(remaining<=0)finishExecutiveGame(false)}function finishExecutiveGame(success){if(!executiveGame)return;clearInterval(executiveTicker);executiveTicker=null;const timer=document.querySelector('#game-timer'),instruction=document.querySelector('#game-instruction'),board=document.querySelector('#game-board'),result=document.querySelector('#game-result');if(board)board.innerHTML='';if(timer)timer.textContent=success?`통과 · ${(Math.max(0,performance.now()-executiveGame.startedAt)/1000).toFixed(2)}초`:'실패';if(instruction)instruction.textContent=success?'5판 모두 맞혔어요!':'10초 안에 5판을 모두 맞히지 못했어요. 다시 도전해보세요.';if(result)result.textContent=success?'타임어택 성공!':'다시 도전';executiveGame=null}function playExecutiveStage(){const game=executiveGame;if(!game)return;const colors=['red','blue','yellow'],labels={red:'빨간',blue:'파란',yellow:'노란'},expected=colors[Math.floor(Math.random()*colors.length)];game.expected=expected;document.querySelector('#game-instruction').textContent=`${game.stage}/5판 · ${labels[expected]}색을 선택하세요`;const order=[...colors];for(let i=order.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[order[i],order[j]]=[order[j],order[i]]}const board=document.querySelector('#game-board');board.innerHTML=`<div class="gem-row">${order.map(color=>`<button class="gem ${color}" data-gem="${color}" aria-label="${labels[color]}색">◆</button>`).join('')}</div>`;board.querySelectorAll('[data-gem]').forEach(button=>button.addEventListener('click',()=>pickExecutiveGem(button.dataset.gem)))}function pickExecutiveGem(color){const game=executiveGame;if(!game)return;if(performance.now()-game.startedAt>=game.duration){finishExecutiveGame(false);return}if(color!==game.expected){const feedback=document.querySelector('#game-feedback');if(feedback)feedback.textContent='다시 골라보세요!';return}const feedback=document.querySelector('#game-feedback');if(feedback)feedback.textContent='';game.score++;game.stage++;if(game.stage>5)finishExecutiveGame(game.score===5&&performance.now()-game.startedAt<=game.duration);else playExecutiveStage()}
const encouragementMessages=['한 번에 하나씩, 충분히 잘하고 있어요.','조금씩 쌓이는 중이에요.','지금의 집중이 좋은 흐름을 만들어요.','잠깐 숨을 고르고 다시 가도 괜찮아요.'];
setInterval(()=>{if(!state.focus.active||state.focus.deviation||!state.settings.character)return;const now=Date.now(),interval=(Number(state.settings.bubbleIntervalMinutes)||15)*60000;if(now-(state.focus.speechAt||state.focus.sessionStartedAt||now)<interval)return;let next=encouragementMessages[Math.floor(Math.random()*encouragementMessages.length)];if(next===state.focus.speech)next=encouragementMessages[(encouragementMessages.indexOf(next)+1)%encouragementMessages.length];state.focus.speech=next;state.focus.speechAt=now;save();if(page==='focus')render()},5000);
function classEndPoll(){if(state.settings.classEndReminders===false)return;const now=new Date(),minute=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`,todayList=todayClasses();for(const cls of todayList){if(cls.end!==minute)continue;const next=todayList.find(item=>item.start===cls.end);if(next)continue;const marker=`class-end-${dayKey()}-${cls.id}`;if(sessionStorage.getItem(marker))continue;sessionStorage.setItem(marker,'1');openClassEndPrompt(cls)}}
function openClassEndPrompt(cls){const root=document.querySelector('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-top"><h2>수업이 끝났어요</h2><button class="close" data-close>×</button></div><p class="page-subtitle">${esc(cls.title)}에서 할 일이 생겼나요? 제목과 마감만 빠르게 기록할 수 있어요.</p><form id="class-end-task"><label class="field-label">할 일 제목<input class="input" name="title" required maxlength="50" placeholder="예: 강의 노트 정리"/></label><label class="field-label">마감일시<input class="input" name="due" type="datetime-local" required value="${localDate(new Date(Date.now()+86400000))}"/></label><div class="modal-actions"><button type="button" class="button ghost" data-skip>나중에</button><button class="button" type="submit">빠르게 추가</button></div></form></section></div>`;root.querySelectorAll('[data-close],[data-skip]').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelector('#class-end-task').onsubmit=e=>{e.preventDefault();const data=new FormData(e.currentTarget),title=String(data.get('title')).trim();state.tasks.push({id:crypto.randomUUID(),title,due:data.get('due'),start:localDate(new Date()),hours:1,priority:'보통',memo:'수업 종료 알림에서 빠르게 추가',done:false,snoozes:0});save();root.innerHTML='';showToast('할 일을 추가했어요')}}
setInterval(classEndPoll,15000);

window.openMissionFromOverlay=()=>go('game');
window.openClassEndFromNotification=title=>openClassEndPrompt({title});

function reconcileLocalDay(){if(document.visibilityState==='visible'&&resetDailyFocusIfNeeded()){save();if(page==='focus')render()}}
document.addEventListener('visibilitychange',reconcileLocalDay);window.addEventListener('focus',reconcileLocalDay);
